// 门点：贴着那条边、再往过道方向外推一点，作为寻路的终点
const DOOR_PAD = 0.006
export function doorPoint(no) {
  const r = mapSpots[no]
  if (!r) return null
  const [x, y, w, h] = r
  switch (mapDoors[no]) {
    case 'A': return { x: x - DOOR_PAD, y: y + h / 2 }
    case 'C': return { x: x + w + DOOR_PAD, y: y + h / 2 }
    case 'B': return { x: x + w / 2, y: y - DOOR_PAD }
    case 'D': return { x: x + w / 2, y: y + h + DOOR_PAD }
    default: return { x: x + w / 2, y: y + h / 2 }
  }
}

// 一个展位号可能对应多个 IP（A01 王者荣耀 / 盛世天下、A14 巫师3 / 赛博朋克 ×2 …），
// booths[].no 是官方展位号原文，同号的多个 IP 用 id 后缀 a/b/c 区分。
const boothsOf = (no) => booths.filter((b) => String(b.no).split('/').some((s) => s.trim() === no))

// 灯箱要的热区数组：rect 归一化坐标，items 为该展位号下的全部 IP
export const mapSpotList = Object.entries(mapSpots).map(([no, rect]) => ({
  no,
  label: `${no[0]}-${no.slice(1)}`,
  rect,
  items: boothsOf(no).map((b) => ({ id: b.id, ip: b.ip })),
}))
